def matroid_representation_size(n):
    return n * (n - 1) // 2

def generate_random_dnf(n, num_terms):
    variables = list(range(1, n + 1))
    dnf = []
    for _ in range(num_terms):
        term = random.sample(variables, random.randint(1, n))
        dnf.append(term)
    return dnf

def term_lattice_size(dnf):
    terms = set(tuple(sorted(term)) for term in dnf)
    lattice_size = len(terms) + 1
    return lattice_size

def run_trial(seed: int) -> dict:
